<?php /** Avis des utilisateurs sur les réponses. */ $cur = 'corrections'; require __DIR__ . '/_nav.php'; ?>
<div class="d-flex gap-2 mb-2 small"><span class="badge text-bg-success">👍 <?= (int) ($stats['up'] ?? 0) ?></span><span class="badge text-bg-danger">👎 <?= (int) ($stats['down'] ?? 0) ?></span><span class="badge text-bg-warning"><?= (int) ($stats['todo'] ?? 0) ?> avis négatif(s) à traiter</span></div>
<div class="card"><?php if (!$rows): ?><div class="card-body small text-secondary">Aucun avis pour l'instant. Les utilisateurs notent une réponse avec les pouces affichés sous chaque message.</div><?php else: ?>
<div class="table-responsive"><table class="table table-sm small mb-0 align-middle"><thead><tr><th>Avis</th><th>Question posée</th><th>Réponse donnée</th><th style="min-width:300px">Traitement</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr class="<?= $r['status'] === 'new' && (int) $r['rating'] < 0 ? 'table-warning' : '' ?>"><td><?= (int) $r['rating'] > 0 ? '👍' : '👎' ?><div class="text-secondary"><?= e(fdate($r['created_at'])) ?></div></td>
  <td><?= e(mb_substr((string) $r['question'], 0, 160)) ?><?= $r['comment'] ? '<div class="text-danger">« ' . e($r['comment']) . ' »</div>' : '' ?></td>
  <td><code><?= e((string) $r['intent']) ?></code><div class="text-secondary"><?= e(mb_substr((string) $r['content'], 0, 140)) ?></div></td>
  <td><?php if ($r['status'] === 'new'): ?><form method="post" action="<?= e(url('/ia/admin/corrections/' . (int) $r['id'])) ?>" class="d-flex gap-1"><?= csrf_field() ?><select name="intent" class="form-select form-select-sm"><option value="">Classer sans suite</option><?php foreach ($intents as $k => $l): ?><option value="<?= e($k) ?>">La bonne intention : <?= e($l) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-primary">Traiter</button></form><?php else: ?><span class="text-secondary">traité</span><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></div>
<p class="small text-secondary mt-2">Choisir « la bonne intention » ajoute la question (anonymisée) aux exemples de cette intention. Rien n'est appris automatiquement : chaque correction passe par vous.</p>
